def infer(a, b):
    m = {}
    for p, s in a.items():
        q = [k for k, v in b.items() if v == s]
        if q: m[p] = q[0]
    return m
def apply(m, a, new=None):
    out = {m[p]: s for p, s in a.items() if p in m}
    for p in a:
        if p not in out.keys() and new is not None and p not in m.values():
            pass
    return out
